/* aesthetic settings v2.17.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-w-medium: 550;
  --ae-radius: 0;
  --ae-space-5: 1.5em;
  --ae-soft: 240ms;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.dark,
[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-settings {
border-bottom: 1px solid var(--ae-line);
}

.ae-setting {
display: flex;
  width: 100%;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--ae-space-5);
  background: transparent;
  border: 0;
  border-top: 1px solid var(--ae-line);
  border-radius: var(--ae-radius);
  padding: 0.8em 0;
  margin: 0;
  font: inherit;
  line-height: inherit;
  color: var(--ae-ink);
  font-weight: var(--ae-w-medium);
  text-align: left;
  cursor: pointer;
}

.ae-setting-val {
color: var(--ae-ink-muted);
  font-weight: var(--ae-w-regular);
  transition: color var(--ae-quick) var(--ae-ease);
}

.ae-setting:hover .ae-setting-val {
color: var(--ae-ink);
}

.ae-setting-panel {
display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--ae-soft) var(--ae-ease);
}

.ae-setting-panel.is-open {
grid-template-rows: 1fr;
}

.ae-setting-panel > * {
overflow: hidden;
  min-height: 0;

  /* the child's border and padding outlive a 0fr row; stop painting
     them once the fold completes */
  visibility: hidden;
  transition: visibility 0s var(--ae-soft);
}

.ae-setting-panel.is-open > * {
visibility: visible;
  transition: visibility 0s;
}

.ae-menu {
margin: 0 0 0.9em;
  padding: 0.3em 0;
  border: 1px solid var(--ae-line);
  background: var(--ae-surface);
  max-height: 14em;
  overflow-y: auto;
}

.ae-menu button {
display: block;
  width: 100%;
  text-align: left;
  background: transparent;
  border: 0;
  border-radius: var(--ae-radius);
  font: inherit;
  font-size: 13px;
  line-height: 1.7;
  color: var(--ae-ink-muted);
  padding: 0.4em 1.1em;
  cursor: pointer;
  transition:
    color var(--ae-quick) var(--ae-ease),
    background-color var(--ae-quick) var(--ae-ease);
}

.ae-menu button:hover {
background: var(--ae-wash);
  color: var(--ae-ink);
}

.ae-menu button.is-sel {
color: var(--ae-ink);
  font-weight: var(--ae-w-medium);
}

/* the popover: geometry for the slip + roving tabindex for its menu.
   Native [popover] owns the top layer, light dismiss, and Escape; this
   recipe places the open slip by its invoker and wires arrow-key
   navigation for any .ae-menu inside.

   <button popovertarget="menu">Options</button>
   <div id="menu" popover class="ae-pop">…</div> */
(() => {
  if (window.aePop) return;
  window.aePop = true;
  document.addEventListener(
    'toggle',
    (e) => {
      const pop = e.target;
      if (!(pop instanceof HTMLElement)) return;
      if (!pop.classList.contains('ae-pop')) return;
      if (e.newState !== 'open' || !pop.id) return;
      const inv = document.querySelector(`[popovertarget="${pop.id}"]`);
      if (!inv) return;
      const r = inv.getBoundingClientRect();
      const pr = pop.getBoundingClientRect();
      let top = r.bottom + 6;
      if (top + pr.height > innerHeight - 8) top = r.top - pr.height - 6;
      const left = Math.min(r.left, innerWidth - pr.width - 8);
      pop.style.top = `${Math.max(8, top)}px`;
      pop.style.left = `${Math.max(8, left)}px`;

      /* roving tabindex: focus the selected item or the first item on
         open, then arrow-key through the menu */
      const menu = pop.querySelector('.ae-menu');
      if (!menu) return;
      const items = [...menu.querySelectorAll('button')].filter(
        (b) => !b.disabled,
      );
      if (items.length === 0) return;
      items.forEach((b) => (b.tabIndex = -1));
      const sel = menu.querySelector('button.is-sel') || items[0];
      sel.tabIndex = 0;
      sel.focus();
    },
    true,
  );

  /* arrow-key roving for .ae-menu inside popovers */
  document.addEventListener('keydown', (e) => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return;
    const menu = e.target.closest('.ae-menu');
    if (!menu) return;
    const items = [...menu.querySelectorAll('button')].filter(
      (b) => !b.disabled,
    );
    if (items.length === 0) return;
    const i = items.indexOf(e.target);
    let next;
    if (e.key === 'ArrowDown') next = items[(i + 1) % items.length];
    else if (e.key === 'ArrowUp')
      next = items[(i - 1 + items.length) % items.length];
    else if (e.key === 'Home') next = items[0];
    else if (e.key === 'End') next = items[items.length - 1];
    if (!next) return;
    e.preventDefault();
    items.forEach((b) => (b.tabIndex = -1));
    next.tabIndex = 0;
    next.focus();
  });
})();

/* settings rows that open: each .ae-setting button toggles the
   .ae-setting-panel that follows it; choosing an option writes the
   row's value and folds the chooser. One row open at a time; Escape
   folds and returns focus. */
(() => {
  const closeSetting = (btn) => {
    const panel = btn.nextElementSibling;
    if (panel) panel.classList.remove('is-open');
    btn.setAttribute('aria-expanded', 'false');
  };
  document.querySelectorAll('.ae-setting').forEach((btn) => {
    const panel = btn.nextElementSibling;
    if (!panel || !panel.classList.contains('ae-setting-panel')) return;
    btn.setAttribute('aria-expanded', 'false');
    btn.addEventListener('click', () => {
      const open = panel.classList.contains('is-open');
      document.querySelectorAll('.ae-setting').forEach(closeSetting);
      if (!open) {
        panel.classList.add('is-open');
        btn.setAttribute('aria-expanded', 'true');
      }
    });
    panel.querySelectorAll('.ae-menu button').forEach((opt) => {
      opt.addEventListener('click', () => {
        panel
          .querySelectorAll('.ae-menu button')
          .forEach((b) => b.classList.toggle('is-sel', b === opt));
        const val = btn.querySelector('.ae-setting-val');
        if (val) val.textContent = opt.dataset.value || opt.textContent.trim();
        closeSetting(btn);
        btn.focus();
      });
    });
    panel.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeSetting(btn);
        btn.focus();
      }
    });
  });
})();
